/**
 * Standard security headers applied to every server response by the
 * `hooks.server.ts` `handle` sequence. The Content Security Policy itself is
 * generated by SvelteKit from the `csp` configuration in vite.config.ts —
 * these are the rest of the baseline (never a replacement for CSP).
 */
export function applySecurityHeaders(response: { headers: Headers }): void {
  response.headers.set("x-content-type-options", "nosniff");
  response.headers.set("referrer-policy", "strict-origin-when-cross-origin");
  response.headers.set("x-frame-options", "SAMEORIGIN");
  response.headers.set(
    "permissions-policy",
    "geolocation=(), camera=(), microphone=(), payment=()",
  );
  response.headers.set("cross-origin-opener-policy", "same-origin");
  response.headers.set("cross-origin-resource-policy", "same-origin");
}
